xpath.script:

document.addEventListener("DOMContentLoaded", function() {
    const product_div = document.getElementsByClassName('js_product').item(0);
    const price_donate_input = document.getElementById('price_donate');
    var dataToSend = {
        'event': 'view-item',
        'donation-name': product_div.getAttribute('data-product-name'),
        'donation-price': price_donate_input.value
    };
    window.parent.postMessage(dataToSend, "https://care.at");
});


document.addEventListener("DOMContentLoaded", function() {
    const product_div = document.getElementsByClassName('js_product').item(0);
    const price_donate_input = document.getElementById('price_donate');
    var dataToSend = {
        'event': 'view-item',
        'donation-name': product_div.getAttribute('data-product-name'),
        'donation-price': price_donate_input.value
    };
    console.log('OPC-Tracking event: %o', dataToSend);
});


document.addEventListener("DOMContentLoaded", function() {
    const cart = document.getElementById('cart_products');
    var dataToSend = {
        'event': 'view-item',
        'donation-name': cart.querySelectorAll('a[name="product_name"]').item(0).text.trim(),
        'donation-price': cart.querySelectorAll('.oe_currency_value').item(0).innerText.trim()
    };
    window.parent.postMessage(dataToSend, "https://care.at");

});


document.addEventListener("DOMContentLoaded", function() {
    const cart = document.getElementById('cart_products');
    var dataToSend = {
        'event': 'view-item',
        'donation-name': cart.querySelectorAll('a[name="product_name"]').item(0).text.trim(),
        'donation-price': cart.querySelectorAll('.oe_currency_value').item(0).innerText.trim()
    };
    console.log('MPC-Tracking event: %o', dataToSend);
});
